export const GetLocationGroupsDocument = new TypedDocumentString(`
    query GetLocationGroups($after: String, $first: Int, $villageId: String) {
  group(
    isDeleted: false
    parentLocation: $villageId
    parentLocationLevel: 3
    first: $first
    after: $after
  ) {
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
    }
    edges {
      node {
        id
        uuid
        code
        head {
          firstName
          lastName
        }
        jsonExt
        groupindividuals(first: 50, isDeleted: false) {
          edges {
            node {
              individual {
                uuid
                benefitconsumptionSet(first: 50, isDeleted: false) {
                  edges {
                    node {
                      id
                      uuid
                      amount
                      dateDue
                      status
                      type
                      payrollbenefitconsumptionSet(first: 5, isDeleted: false) {
                        edges {
                          node {
                            payroll {
                              paymentCycle {
                                code
                                startDate
                                endDate
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
    `) as unknown as TypedDocumentString<GetLocationGroupsQuery, GetLocationGroupsQueryVariables>;
